import { Injectable, signal } from '@angular/core';

export interface ToastMessage {
  id: number;
  text: string;
  type: 'info' | 'success' | 'error';
}

@Injectable({ providedIn: 'root' })
export class ToastService {
  private _toasts = signal<ToastMessage[]>([]);
  private nextId = 0;

  readonly toasts = this._toasts.asReadonly();

  /** Show a toast message. Auto-dismisses after duration (ms). Returns the toast ID. */
  show(text: string, type: 'info' | 'success' | 'error' = 'info', duration = 3000): number {
    const id = this.nextId++;
    this._toasts.update(t => [...t, { id, text, type }]);

    if (duration > 0) {
      setTimeout(() => this.dismiss(id), duration);
    }

    return id;
  }

  /** Dismiss a specific toast by ID */
  dismiss(id: number): void {
    this._toasts.update(t => t.filter(m => m.id !== id));
  }

  /** Update the text of an existing toast */
  update(id: number, text: string, type?: 'info' | 'success' | 'error'): void {
    this._toasts.update(toasts =>
      toasts.map(t => t.id === id ? { ...t, text, ...(type ? { type } : {}) } : t)
    );
  }
}
